import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.sN6AQ-fu.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),s={name:"guide/introduction.md"};function n(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Mayhem is one desktop app for a robot&#39;s software: build pose-based autos, inspect state machines, analyze match logs, see what&#39;s running on the robot, review what a code change actually does, and turn team feedback into tasks for coding agents.</p><h2 id="choose-your-workflow" tabindex="-1">Choose your workflow <a class="header-anchor" href="#choose-your-workflow" aria-label="Permalink to &quot;Choose your workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to</th><th>Start here</th></tr></thead><tbody><tr><td>Install the app</td><td><a href="/Mayhem/guide/installation">Installation</a></td></tr><tr><td>Build an auto</td><td><a href="/Mayhem/guide/quick-start">Your first routine</a>, then <a href="/Mayhem/suite/autonomous">Autonomous</a></td></tr><tr><td>Find your way around</td><td><a href="/Mayhem/suite/overview">The app at a glance</a></td></tr><tr><td>Review a robot code change</td><td><a href="/Mayhem/suite/changes">Changes</a></td></tr><tr><td>Hand work to agents</td><td><a href="/Mayhem/suite/tasks">Tasks</a></td></tr><tr><td>Keep using solver <code>.mtraj</code> paths and Java MayhemLib</td><td><a href="/Mayhem/guide/classic-quick-start">Classic trajectory quick start</a></td></tr><tr><td>Work on Mayhem itself</td><td><a href="/Mayhem/reference/building">Building and contributing</a></td></tr></tbody></table><h2 id="the-workspaces" tabindex="-1">The workspaces <a class="header-anchor" href="#the-workspaces" aria-label="Permalink to &quot;The workspaces&quot;">​</a></h2><ul><li><strong><a href="/Mayhem/suite/overview">Overview</a>:</strong> routine thumbnails, latest logs, the match-ready checklist and a clickable robot explainer.</li><li><strong><a href="/Mayhem/suite/changes">Changes</a>:</strong> what a code change does to controls, state machines, values, hardware and autos, with a before/after sim proof.</li><li><strong><a href="/Mayhem/suite/tasks">Tasks</a>:</strong> feedback, pit notes and driver forms become agent tasks; approve plans and check changes.</li><li><strong><a href="/Mayhem/suite/autonomous">Autonomous</a>:</strong> place goals, add actions and conditions, preview the path or the full routine.</li><li><strong><a href="/Mayhem/suite/state-machines">State machines</a>:</strong> graphs in simulation, live over NT4, or replayed from a log.</li><li><strong><a href="/Mayhem/suite/logs">Logs</a>:</strong> findings, power, signals and pose replay for every recording.</li><li><strong><a href="/Mayhem/suite/robot">Robot</a>:</strong> what&#39;s on the robot now, every value in the code, specs, connection and log collection.</li></ul><p>Preview doesn&#39;t run your custom robot code or avoid obstacles, and the C++ pose controller still needs tuning on the real robot. See the <a href="https://github.com/ryanabraham1/Mayhem/blob/main/docs/SUITE_STATUS.md" target="_blank" rel="noreferrer">implementation status</a> for what&#39;s been verified.</p><h2 id="classic-trajectory-planner" tabindex="-1">Classic trajectory planner <a class="header-anchor" href="#classic-trajectory-planner" aria-label="Permalink to &quot;Classic trajectory planner&quot;">​</a></h2><p>Open <strong>Settings → Classic trajectory planner → Open classic planner</strong> for existing paths. The Python CasADi/IPOPT solver generates time-optimal trajectories with drivetrain limits and swept bumper collision checks, and Java MayhemLib follows the exported <code>.mtraj</code> files. These files and APIs are separate from suite projects and the C++ pose controller. The <strong>Classic planner</strong> and <strong>MayhemLib</strong> sections document that workflow.</p>',9)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
